func fleetScheduleLabel(row sysRow) string {
	switch row.Key {
	case "BACKUP_DAYS":
		return "Days"
	case "BACKUP_TIME":
		return "Time"
	case "BACKUP_KEEP":
		return "Kept per device"
	case "BACKUP_MAX_AGE":
		return "Never prune younger than"
	}
	return row.Label
}

func fleetScheduleValue(row sysRow) string {
	switch row.Key {
	case "BACKUP_DAYS":
		if row.Value == "" {
			return "None: manual only"
		}
		days := strings.Split(row.Value, ",")
		for i, d := range days {
			days[i] = dayLabels[d]
		}
		return strings.Join(days, ", ")
	}
	return row.Value
}

